		public bool Message(in global::Dpr.Battle.Logic.StrParam strParam) {
            ushort strID = strParam.GetStrID();
            ushort argsCount = strParam.GetArgsCount();
            int[] args = strParam.GetArgs();
            if (strParam.IsSEAdded())
            {
                uint seNo = (uint)strParam.GetSE();
                BtlStrType strType = strParam.GetStrType();
                if (strType == BtlStrType.BTL_STRTYPE_SET)
                    Message_SetSE(strID, seNo, argsCount, args);
                else if (strType == BtlStrType.BTL_STRTYPE_STD)
                    Message_StdSE(strID, seNo, argsCount, args);
                else
                    return false;
            }
            else
            {
                BtlStrType strType = strParam.GetStrType();
                if (strType == BtlStrType.BTL_STRTYPE_SET)
                    Message_SetEx(strID, argsCount, args);
                else if (strType == BtlStrType.BTL_STRTYPE_STD)
                    Message_StdEx(strID, argsCount, args);
                else
                    return false;
            }
            return true;
        }
