		public void Message_StdEx(ushort strID, uint argsCount, int[] args) {
            switch (argsCount)
            {
                case 1:
                    Message_Std(strID, args[0]);
                    break;
                case 2:
                    Message_Std(strID, args[0], args[1]);
                    break;
                case 3:
                    Message_Std(strID, args[0], args[1], args[2]);
                    break;
                case 4:
                    Message_Std(strID, args[0], args[1], args[2], args[3]);
                    break;
                default:
                    Message_Std(strID);
                    break;
            }
        }
