		public void Message_DamageAffinity(global::Pml.Battle.TypeAffinity.AffinityID affinity) {
            if (affinity < TypeAffinity.AffinityID.TYPEAFF_1)
                SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.AffBad });
            else if (affinity != TypeAffinity.AffinityID.TYPEAFF_1)
                SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.AffGood });
        }
		public void Message_WazaAffinity(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, uint targetCount, global::Pml.Battle.TypeAffinity.AffinityID[] affinityArray, global::Dpr.Battle.Logic.BTL_POKEPARAM[] targets, bool isPluralHitWaza) {
            byte goodCount = 0;
            byte badCount = 0;
            for (int i = 0; i < targetCount; i++)
            {
                if (affinityArray[i] > TypeAffinity.AffinityID.TYPEAFF_1)
                    goodCount++;
                else if (affinityArray[i] < TypeAffinity.AffinityID.TYPEAFF_1)
                    badCount++;
            }

            if (!isPluralHitWaza)
            {
                if (goodCount != 0)
                {
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.AffGood });
                    if (SectionUtil.GetFriendship(m_pMainModule, attacker) == 255)
                    {
                        byte attackerID = attacker.GetID();
                        SCQUE_PUT_ACT_FriendshipEffectWithMsg(m_pQueue, attackerID, FriendshipEffect.FREFF_FURIMUKI, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.FR_AffGood, attackerID, 0);
                    }
                }
                else if (badCount != 0)
                {
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.AffBad });
                }
                return;
            }

            if (goodCount != 0)
            {
                PokeIDRegister goodPokes = new PokeIDRegister();
                for (int i = 0; i < targetCount; i++)
                {
                    if (affinityArray[i] > TypeAffinity.AffinityID.TYPEAFF_1)
                        goodPokes.Register(targets[i].GetID());
                }
                switch (goodCount)
                {
                    case 1:
                        SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.AffGood_1, goodPokes[0] });
                        break;
                    case 2:
                        SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.AffGood_2, goodPokes[0], goodPokes[1] });
                        break;
                    case 3:
                        SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.AffGood_3, goodPokes[0], goodPokes[1], goodPokes[2] });
                        break;
                    case 4:
                        SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.AffGood_4, goodPokes[0], goodPokes[1], goodPokes[2], goodPokes[3] });
                        break;
                }
                if (SectionUtil.GetFriendship(m_pMainModule, attacker) == 255)
                {
                    byte attackerID = attacker.GetID();
                    SCQUE_PUT_ACT_FriendshipEffectWithMsg(m_pQueue, attackerID, FriendshipEffect.FREFF_FURIMUKI, BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.FR_AffGood, attackerID, 0);
                }
            }

            if (badCount != 0)
            {
                PokeIDRegister badPokes = new PokeIDRegister();
                for (int i = 0; i < targetCount; i++)
                {
                    if (affinityArray[i] < TypeAffinity.AffinityID.TYPEAFF_1)
                        badPokes.Register(targets[i].GetID());
                }
                switch (badCount)
                {
                    case 1:
                        SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.AffBad_1, badPokes[0] });
                        break;
                    case 2:
                        SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.AffBad_2, badPokes[0], badPokes[1] });
                        break;
                    case 3:
                        SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.AffBad_3, badPokes[0], badPokes[1], badPokes[2] });
                        break;
                    case 4:
                        SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.AffBad_4, badPokes[0], badPokes[1], badPokes[2], badPokes[3] });
                        break;
                }
            }
        }
