		public void Message_WazaExecuteFailed(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, global::Pml.WazaNo waza, global::Dpr.Battle.Logic.WazaFailCause cause) {
            byte pokeID = attacker.GetID();
            switch (cause)
            {
                case WazaFailCause.PP_ZERO:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.PP_Short, pokeID });
                    break;
                case WazaFailCause.NEMURI:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.NemuriAct, pokeID });
                    if (m_pMainModule.GetPokeFriendship(attacker) == 255)
                        SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.FR_Sleep });
                    break;
                case WazaFailCause.MAHI:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.MahiAct, pokeID });
                    break;
                case WazaFailCause.KOORI:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.KoriAct, pokeID });
                    break;
                case WazaFailCause.SHRINK:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.ShrinkExe, pokeID });
                    break;
                case WazaFailCause.KIAI_SHRINK:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.KiaiShrink, pokeID });
                    break;
                case WazaFailCause.MEROMERO:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.MeromeroExe, pokeID });
                    break;
                case WazaFailCause.KANASIBARI:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.KanasibariWarn, pokeID, (int)waza });
                    break;
                case WazaFailCause.TYOUHATSU:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.ChouhatuWarn, pokeID, (int)waza });
                    break;
                case WazaFailCause.ICHAMON:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.IchamonWarn, pokeID, (int)waza });
                    break;
                case WazaFailCause.FUUIN:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.FuuinWarn, pokeID, (int)waza });
                    break;
                case WazaFailCause.KAIHUKUHUUJI:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.KaifukuFujiWarn, pokeID, (int)waza });
                    break;
                case WazaFailCause.HPFULL:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.HPFull, pokeID });
                    break;
                case WazaFailCause.FUMIN:
                    // SCQUE_PUT_TOKWIN_IN/OUT inlined (their flags 0x4cbf61d/61e mid-body); no PokeID.INVALID test, so not TokWin_In/Out
                    SCQUE_PUT_TOKWIN_IN(m_pQueue, pokeID);
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.Fumin, pokeID });
                    SCQUE_PUT_TOKWIN_OUT(m_pQueue, pokeID);
                    break;
                case WazaFailCause.ENCORE:
                    // shipped: ENCORE prints SET 0x25a (Namake); NAMAKE itself falls to the default WazaFail message
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.Namake, pokeID });
                    break;
                case WazaFailCause.TOKUSEI:
                case WazaFailCause.NO_REACTION:
                    break;
                case WazaFailCause.JURYOKU:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.JyuryokuWazaFail, pokeID, (int)waza });
                    break;
                case WazaFailCause.SABOTAGE:
                    if (attacker.CheckNemuri(BTL_POKEPARAM.NemuriCheckMode.NEMURI_CHECK_ONLY_SICK))
                    {
                        SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.Sabotage_Sleeping, pokeID });
                    }
                    else
                    {
                        byte rand = (byte)calc.GetRand(4);
                        SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.Sabotage1 + rand, pokeID });
                    }
                    break;
                case WazaFailCause.SABOTAGE_GO_SLEEP:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.Sabotage_GoSleep, pokeID });
                    break;
                case WazaFailCause.SKYBATTLE:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.SkyBattleFail });
                    break;
                case WazaFailCause.OOAME:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.RainStormFail });
                    break;
                case WazaFailCause.OOHIDERI:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.DayFail });
                    break;
                case WazaFailCause.IJIGEN_FOOPA:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.IjigemRushFail_Foopa, pokeID });
                    break;
                case WazaFailCause.IJIGEN_OTHER:
                case WazaFailCause.DARKHOLE_OTHER:
                case WazaFailCause.OORAGURUMA_OTHER:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.IjigemRushFail_Another, pokeID });
                    break;
                case WazaFailCause.ZIGOKUDUKI:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.Zigokuduki_Warn, pokeID });
                    break;
                case WazaFailCause.TRAPSHELL:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.TrapShell_Failed, pokeID });
                    break;
                case WazaFailCause.TARGET_IS_G:
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.WazaFail_TargetIsG, pokeID });
                    break;
                case WazaFailCause.TARGET_IS_RAIDBOSS:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.RAID_WazaFailed, pokeID });
                    break;
                case WazaFailCause.VS_JOKER2_PLAYER:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.vsJoker_00, pokeID });
                    break;
                case WazaFailCause.VS_JOKER2_JOKER:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.vsJoker_01, pokeID });
                    break;
                default:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.WazaFail, pokeID });
                    break;
            }
        }
