		public void Message_AddSickFailed(global::Dpr.Battle.Logic.BTL_POKEPARAM target, global::Dpr.Battle.Logic.AddSickFailCode failCode, global::Pml.WazaData.WazaSick sick, global::Dpr.Battle.Logic.SickCause cause) {
            byte pokeID = target.GetID();
            switch (failCode)
            {
                case AddSickFailCode.GWALL:
                    SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.RAID_Boss_00, pokeID });
                    return;
                case AddSickFailCode.NO_EFFECT:
                    if (cause == SickCause.WAZA_EFFECT_SICK)
                    {
                        short strID = BTL_SICK.GetSpecificSickFailStrID(sick);
                        if (strID >= 0)
                        {
                            SCQUE_PUT_MSG_SET(m_pQueue, new int[] { strID, pokeID });
                            return;
                        }
                    }
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.NoEffect, pokeID });
                    return;
                case AddSickFailCode.ALREADY:
                    // byte jump table @03d5c7a6 (sick - 1, 20 entries): unlisted sicks fall to the WazaFail message below
                    switch (sick)
                    {
                        case WazaSick.WAZASICK_MAHI:
                            SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.MahiAlready, pokeID });
                            return;
                        case WazaSick.WAZASICK_NEMURI:
                            SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.NemuriAlready, pokeID });
                            return;
                        case WazaSick.WAZASICK_KOORI:
                            SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.KoriAlready, pokeID });
                            return;
                        case WazaSick.WAZASICK_YAKEDO:
                            SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.YakedoAlready, pokeID });
                            return;
                        case WazaSick.WAZASICK_DOKU:
                            SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.DokuAlready, pokeID });
                            return;
                        case WazaSick.WAZASICK_KONRAN:
                            SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.KonranAlready, pokeID });
                            return;
                        case WazaSick.WAZASICK_KAIHUKUHUUJI:
                            SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.WazaFailPoke, pokeID });
                            return;
                        case WazaSick.WAZASICK_HOROBINOUTA:
                            return;
                    }
                    break;
            }
            SCQUE_PUT_MSG_STD(m_pQueue, new int[] { BTL_STRID_STD.WazaFail });
        }
