		public void SimpleHp(global::Dpr.Battle.Logic.BTL_POKEPARAM poke, int value, global::Dpr.Battle.Logic.DamageCause damageCause, byte damageCausePokeID, bool isEffectEnable) {
            byte pokeID = poke.GetID();
            if (value > 0)
            {
                poke.HpPlus((ushort)value);
                SCQUE_PUT_OP_HpPlus(m_pQueue, pokeID, (ushort)value);
            }
            else if (value < 0)
            {
                DecreaseHP(poke, (uint)(-value), false, damageCause, damageCausePokeID);
            }

            if (isEffectEnable && m_pBattleEnv.GetPosPoke().GetPokeExistPos(pokeID) != BtlPokePos.POS_NULL)
                SCQUE_PUT_ACT_SimpleHP(m_pQueue, pokeID);
        }
		public void DecreaseHP(global::Dpr.Battle.Logic.BTL_POKEPARAM poke, uint value, bool byWazaDamage, global::Dpr.Battle.Logic.DamageCause damageCause, byte damageCausePokeID) {
            m_pExecutor.HPMinus(poke.GetID(), value, damageCause, damageCausePokeID);
            if (byWazaDamage)
                SCQUE_PUT_OP_HpMinusForSyncWazaEffect(m_pQueue, poke.GetID(), (ushort)value, damageCause, damageCausePokeID);
            else
                SCQUE_PUT_OP_HpMinus(m_pQueue, poke.GetID(), (ushort)value, damageCause, damageCausePokeID);
        }
		public void ConfDamage(global::Dpr.Battle.Logic.BTL_POKEPARAM poke, uint damage) {
            BTL_SICKCONT sickCont = poke.GetSickCont(WazaSick.WAZASICK_KONRAN);
