		public void AddSick(global::Dpr.Battle.Logic.BTL_POKEPARAM target, global::Pml.WazaData.WazaSick sick, in global::Dpr.Battle.Logic.BTL_SICKCONT sickCont) {
            byte pokeID = target.GetID();
            target.SetWazaSick(sick, sickCont);
            SCQUE_PUT_OP_SetSick(m_pQueue, pokeID, (byte)sick, sickCont);
            if (BattleCommon.IsPokeSick(sick))
            {
                Sick iconSick = (Sick)sick;
                if (sick == WazaSick.WAZASICK_DOKU)
                    iconSick = SICKCONT.IsMoudokuCont(sickCont) ? (Sick)6 : Sick.DOKU; // 6 = MOUDOKU icon (cinc @01f19938; Pml Sick has no member, 6 = MAX)
                SCQUE_PUT_ACT_SickIcon(m_pQueue, pokeID, iconSick);
            }
        }
		public void CureSick(global::Dpr.Battle.Logic.BTL_POKEPARAM poke, global::Pml.WazaData.WazaSick sick, out global::Dpr.Battle.Logic.BTL_SICKCONT pOldCont) {
            if (sick == WazaSick.WAZASICK_NONE)
            {
                pOldCont = SICKCONT.MakeNull();
                return;
            }

            pOldCont = poke.GetSickCont(sick);
            byte pokeID = poke.GetID();
            bool isPokeSick = BattleCommon.IsPokeSick(sick);
            if (isPokeSick)
            {
                m_pExecutor.CurePokeSick(pokeID);
                SCQUE_PUT_OP_CurePokeSick(m_pQueue, pokeID);
                if (m_pBattleEnv.GetPosPoke().GetPokeExistPos(pokeID) != BtlPokePos.POS_NULL)
                    SCQUE_PUT_ACT_SickIcon(m_pQueue, pokeID, Sick.NONE);
            }
            else
            {
                m_pExecutor.CureWazaSick(pokeID, sick);
                SCQUE_PUT_OP_CureWazaSick(m_pQueue, pokeID, (ushort)sick);
            }
        }
