		public void RankEffect(global::Dpr.Battle.Logic.BTL_POKEPARAM target, global::Pml.WazaData.WazaRankEffect effect, int volume, ushort itemID, bool putStdMsg, global::Dpr.Battle.Logic.RankEffectViewType viewType) {
            byte pokeID = target.GetID();
            if (effect == WazaRankEffect.CRITICAL_RATIO)
            {
                if (volume > 0)
                {
                    AddCriticalRank(target.GetID(), (byte)volume);
                    if (viewType != RankEffectViewType.DISABLE)
                        SCQUE_PUT_ACT_RankUp(m_pQueue, pokeID, (byte)WazaRankEffect.CRITICAL_RATIO, (byte)volume, viewType);
                    if (putStdMsg)
                        Message_Set(BTL_STRID_SET.KiaiDame, target.GetID());
                }
            }
            else if (volume > 0)
            {
                byte result = target.RankUp((BTL_POKEPARAM.ValueID)effect, (byte)volume);
                SCQUE_PUT_OP_RankUp(m_pQueue, pokeID, (byte)effect, result);
                if (viewType != RankEffectViewType.DISABLE)
                    SCQUE_PUT_ACT_RankUp(m_pQueue, pokeID, (byte)effect, result, viewType);
                if (putStdMsg)
                {
                    if (itemID != 0)
                        SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.UseItem_Rankup_ATK, pokeID, itemID, (int)effect, result });
                    else
                        SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.Rankup_ATK, pokeID, (int)effect, result });
                }
            }
            else
            {
                byte result = target.RankDown((BTL_POKEPARAM.ValueID)effect, (byte)(-volume));
                SCQUE_PUT_OP_RankDown(m_pQueue, pokeID, (byte)effect, result);
                if (viewType != RankEffectViewType.DISABLE)
                    SCQUE_PUT_ACT_RankDown(m_pQueue, pokeID, (byte)effect, result, viewType);
                if (putStdMsg)
                    SCQUE_PUT_MSG_SET(m_pQueue, new int[] { BTL_STRID_SET.Rankdown_ATK, pokeID, (int)effect, result });
            }
        }
