		public void WazaEffect(in global::Dpr.Battle.Logic.WazaParam wazaParam, global::Dpr.Battle.Logic.WazaEffectParams wazaEffect, in global::Dpr.Battle.Logic.WazaEffectReservedPos reservedQueuePos) {
            WazaNo waza = wazaEffect.effectWazaID;
            if (waza == WazaNo.NULL)
                waza = wazaParam.wazaID;

            if (wazaEffect.IsSubEffectParamsValid())
            {
                WazaSubEffect(wazaEffect, reservedQueuePos.prevEffectCmd);
                wazaEffect.ClearSubEffectParams();
            }

            if (reservedQueuePos.IsValid())
            {
                m_pQueue.Put_ToReservedPos(reservedQueuePos.mainEffectCmd, ServerCommand.ACT_WAZA_EFFECT, new int[] {
                    (int)wazaEffect.attackerPos, (int)wazaEffect.targetPos, (int)waza, wazaParam.wazaType,
                    wazaEffect.effectIndex, wazaEffect.pluralHitIndex, wazaEffect.isSyncDamageEffect ? 1 : 0, wazaEffect.isGShockOccur ? 1 : 0 });
            }
            else
            {
                SCQUE_PUT_ACT_WazaEffect(m_pQueue, wazaEffect.attackerPos, wazaEffect.targetPos, waza, wazaParam.wazaType,
                    wazaEffect.effectIndex, wazaEffect.pluralHitIndex, wazaEffect.isSyncDamageEffect, wazaEffect.isGShockOccur);
            }
            wazaEffect.effectIndex = 0;
            wazaEffect.fDone = true;
        }
		public void WazaSubEffect(global::Dpr.Battle.Logic.WazaEffectParams wazaEffect, ushort reservedQuePos) {
            // shipped: the sub-effect is written with the ACT_KINOMI_PRE_WAZA command (0x97) and its 6-int layout
            m_pQueue.Put_ToReservedPos(reservedQuePos, ServerCommand.ACT_KINOMI_PRE_WAZA, new int[] {
                wazaEffect.subEff_pokeCnt, wazaEffect.subEff_pokeID_1, wazaEffect.subEff_pokeID_2,
                wazaEffect.subEff_pokeID_3, wazaEffect.subEff_pokeID_4, wazaEffect.subEff_pokeID_5 });
        }
