		public void WazaDamagePlural(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, global::Dpr.Battle.Logic.WazaParam wazaParam, uint targetCount, global::Dpr.Battle.Logic.BTL_POKEPARAM[] targets, global::Pml.Battle.TypeAffinity.AffinityID[] affinityArray, ushort[] damage) {
            byte goodCount = 0;
            byte badCount = 0;
            for (int i = 0; i < targetCount; i++)
            {
                DecreaseHP(targets[i], damage[i], true, DamageCause.WAZA, attacker.GetID());
                if (affinityArray[i] > TypeAffinity.AffinityID.TYPEAFF_1)
                    goodCount++;
                else if (affinityArray[i] < TypeAffinity.AffinityID.TYPEAFF_1)
                    badCount++;
            }

            TypeAffinity.AboutAffinityID affAbout;
            if (goodCount != 0)
                affAbout = TypeAffinity.AboutAffinityID.ADVANTAGE;
            else if (badCount != 0)
                affAbout = TypeAffinity.AboutAffinityID.DISADVANTAGE;
            else
                affAbout = TypeAffinity.AboutAffinityID.NORMAL;

            m_pQueue.Put_ExArgStart((byte)(targetCount * 2));
            for (int i = 0; i < targetCount; i++)
            {
                m_pQueue.Put_ExArgOnly(targets[i].GetID());
                m_pQueue.Put_ExArgOnly((byte)affinityArray[i]);
            }
            SCQUE_PUT_ACT_WazaDamagePlural(m_pQueue, (byte)targetCount, (byte)affAbout, (ushort)wazaParam.wazaID);
        }
