		public void ReserveUseItemCommands(global::Dpr.Battle.Logic.ServerCommandPutter.UseItemCommandParam pParam) {
            pParam.cmdQueuePos_TokuseiWindowIn = m_pQueue.ReservePutPos(ServerCommand.TOKWIN_IN);
            pParam.cmdQueuePos_ItemUseAction = m_pQueue.ReservePutPos(ServerCommand.ACT_USE_ITEM);
            pParam.cmdQueuePos_TokuseiWindowOut = m_pQueue.ReservePutPos(ServerCommand.TOKWIN_OUT);
        }
		public void PutUseItemCommands(in global::Dpr.Battle.Logic.ServerCommandPutter.UseItemCommandParam param) {
            if (param.needTokuseiWindowDisplay)
                m_pQueue.Put_ToReservedPos(param.cmdQueuePos_TokuseiWindowIn, ServerCommand.TOKWIN_IN, new int[] { param.pokeID });

            bool isNuts = Pml.Item.ItemData.IsNuts(param.itemno);
            m_pQueue.Put_ToReservedPos(param.cmdQueuePos_ItemUseAction, ServerCommand.ACT_USE_ITEM, new int[] { param.pokeID, isNuts ? 1 : 0 });

            if (param.needTokuseiWindowDisplay)
                m_pQueue.Put_ToReservedPos(param.cmdQueuePos_TokuseiWindowOut, ServerCommand.TOKWIN_OUT, new int[] { param.pokeID });
        }
